"""Build and follow a source-shaped 90-degree route through a divider opening.

The waypoint check proves planar clearance for the authored vehicle footprint.
Actual Native motion, barrier contact and public authority require local review.
"""

import math

from shapely.geometry import LineString, Point, Polygon


def _polygon(points, label):
    shape = Polygon(points)
    if not shape.is_valid or shape.area <= 0:
        raise ValueError('Invalid ' + label)
    return shape


def validate_route(context, points, *, body_radius_m):
    """Return a clearance receipt for an ordered right-roadway to left-turn path."""
    if len(points) < 4 or not 0 < body_radius_m < 10:
        raise ValueError('Route needs four points and a positive body radius')
    path = LineString(points)
    if not path.is_simple or path.length <= 0:
        raise ValueError('Route self-intersects or has zero length')
    right = _polygon(context['right_hand_roadway_xy_m'], 'right-hand roadway')
    destination = _polygon(context['destination_roadway_xy_m'], 'destination roadway')
    divider = _polygon(context['dividing_space_xy_m'], 'dividing space')
    opening = _polygon(context['opening_xy_m'], 'opening')
    if not divider.covers(opening):
        raise ValueError('Opening is outside dividing space')
    if not right.covers(Point(points[0])) or not destination.covers(Point(points[-1])):
        raise ValueError('Route does not join the assigned roadways')
    swept = path.buffer(body_radius_m, cap_style=2, join_style=2)
    if swept.intersection(divider.difference(opening)).area > 1e-7:
        raise ValueError('Complete-body route crosses blocked dividing space')
    if not swept.intersects(opening):
        raise ValueError('Route does not traverse physical opening')
    first = (points[1][0] - points[0][0], points[1][1] - points[0][1])
    last = (points[-1][0] - points[-2][0], points[-1][1] - points[-2][1])
    angle = math.degrees(math.atan2(first[0]*last[1]-first[1]*last[0],
                                    first[0]*last[0]+first[1]*last[1]))
    if not 60 <= angle <= 120:
        raise ValueError('Selected maneuver is not a 90-degree left turn')
    return {'route_length_m': path.length, 'body_radius_m': body_radius_m,
            'opening_traversed': True, 'blocked_space_clearance': True,
            'turn_angle_degrees': angle, 'legal_conclusion': 'unresolved'}


class WaypointController:
    """Apply bounded steer/throttle to a Native vehicle using route waypoints."""

    def __init__(self, points, *, arrival_radius_m=1.25):
        if len(points) < 2 or arrival_radius_m <= 0:
            raise ValueError('Incomplete waypoint controller')
        self.points = tuple((float(x), float(y)) for x, y in points)
        self.arrival_radius_m = arrival_radius_m
        self.index = 1

    def step(self, vehicle):
        location = vehicle.get_transform().location
        position = (float(location.x), float(location.y))
        while self.index < len(self.points)-1 and math.dist(position, self.points[self.index]) <= self.arrival_radius_m:
            self.index += 1
        target = self.points[self.index]
        yaw = math.radians(float(vehicle.get_transform().rotation.yaw))
        desired = math.atan2(target[1]-position[1], target[0]-position[0])
        error = math.atan2(math.sin(desired-yaw), math.cos(desired-yaw))
        arrived = self.index == len(self.points)-1 and math.dist(position, target) <= self.arrival_radius_m
        import carla
        control = carla.VehicleControl(throttle=0.0 if arrived else 0.27,
                                       steer=max(-0.7, min(0.7, error)),
                                       brake=1.0 if arrived else 0.0)
        vehicle.apply_control(control)
        return {'waypoint_index': self.index, 'arrived': arrived,
                'steer': control.steer, 'throttle': control.throttle}


def validate_blocked_space_route(context, points, barrier_footprints, *, body_radius_m):
    """Plan a diagnostic crossing of divider space outside the named opening.

    A path into a physical barrier is rejected. This geometry does not decide
    whether an unbarriered corridor is a statutory opening; source review must.
    """
    if len(points) < 4 or not 0 < body_radius_m < 10:
        raise ValueError('Complete blocked-space route and body radius required')
    path = LineString(points)
    if not path.is_simple or path.length <= 0:
        raise ValueError('Invalid blocked-space route')
    right = _polygon(context['right_hand_roadway_xy_m'], 'right-hand roadway')
    destination = _polygon(context['destination_roadway_xy_m'], 'destination roadway')
    divider = _polygon(context['dividing_space_xy_m'], 'dividing space')
    opening = _polygon(context['opening_xy_m'], 'opening')
    if not right.covers(Point(points[0])) or not destination.covers(Point(points[-1])):
        raise ValueError('Blocked-space route does not join roadways')
    swept = path.buffer(body_radius_m, cap_style=2, join_style=2)
    if swept.intersection(opening).area > 1e-7:
        raise ValueError('Blocked-space route enters named opening')
    if swept.intersection(divider.difference(opening)).area <= 1e-7:
        raise ValueError('Route does not cross named blocked dividing space')
    if not barrier_footprints:
        raise ValueError('Realized physical barrier footprints required')
    for footprint in barrier_footprints:
        if swept.intersects(_polygon(footprint, 'realized barrier')):
            raise ValueError('Route collides with physical barrier')
    first = (points[1][0]-points[0][0], points[1][1]-points[0][1])
    last = (points[-1][0]-points[-2][0], points[-1][1]-points[-2][1])
    angle = math.degrees(math.atan2(first[0]*last[1]-first[1]*last[0],
                                    first[0]*last[0]+first[1]*last[1]))
    if not 60 <= angle <= 120:
        raise ValueError('Blocked-space comparison needs a left turn')
    return {'route_length_m': path.length, 'body_radius_m': body_radius_m,
            'named_opening_traversed': False, 'divider_outside_opening_traversed': True,
            'realized_barrier_clearance': True, 'turn_angle_degrees': angle,
            'statutory_opening_judgment': 'unresolved', 'legal_conclusion': 'unresolved'}


def validate_right_roadway_continuation(context, points, *, body_radius_m):
    """Plan the fixed-site no-turn comparator wholly on the right-hand roadway."""
    if len(points) < 2 or not 0 < body_radius_m < 10:
        raise ValueError('Continuation route and body radius required')
    path = LineString(points)
    if not path.is_simple or path.length <= 0:
        raise ValueError('Invalid continuation route')
    right = _polygon(context['right_hand_roadway_xy_m'], 'right-hand roadway')
    swept = path.buffer(body_radius_m, cap_style=2, join_style=2)
    if not right.covers(swept):
        raise ValueError('Complete-body continuation leaves right-hand roadway')
    first = (points[1][0]-points[0][0], points[1][1]-points[0][1])
    last = (points[-1][0]-points[-2][0], points[-1][1]-points[-2][1])
    angle = math.degrees(math.atan2(first[0]*last[1]-first[1]*last[0],
                                    first[0]*last[0]+first[1]*last[1]))
    if abs(angle) > 15:
        raise ValueError('Continuation comparator turns')
    return {'route_length_m': path.length, 'body_radius_m': body_radius_m,
            'right_roadway_swept_clearance': True, 'turn_angle_degrees': angle,
            'legal_conclusion': 'unresolved'}


def validate_crossover_route(context, points, crossover_xy_m, *, body_radius_m):
    """Require an opening route through the sourced crossover footprint.

    The separate administrative establishment source is checked by the runner;
    this geometry alone cannot establish its public-authority status.
    """
    opening = validate_route(context, points, body_radius_m=body_radius_m)
    crossover = _polygon(crossover_xy_m, 'crossover')
    swept = LineString(points).buffer(body_radius_m, cap_style=2, join_style=2)
    if swept.intersection(crossover).area <= 1e-7:
        raise ValueError('Route misses sourced crossover footprint')
    return {**opening, 'crossover_footprint_traversed': True,
            'public_authority_establishment_judgment': 'unresolved'}

"""Spawn two real barrier sections with a traversable median opening between.

The supplied blueprints/transforms are source-reviewed. The CPU geometry check
does not prove public-authority establishment or physical drivability.
"""

from contextlib import contextmanager
import math

from shapely.geometry import MultiPoint, Polygon


def _xy(value):
    x,y=float(value.x),float(value.y)
    if not math.isfinite(x) or not math.isfinite(y):raise ValueError("Nonfinite barrier geometry")
    return x,y


@contextmanager
def spawn_barrier_opening(world,sections,opening_xy_m,barrier_axis_xy):
    if len(sections)!=2:raise ValueError("Exactly two physical barrier sections required")
    opening=Polygon(opening_xy_m)
    if not opening.is_valid or opening.area<=0:raise ValueError("Invalid opening footprint")
    ax,ay=map(float,barrier_axis_xy)
    norm=math.hypot(ax,ay)
    if not math.isfinite(norm) or norm<=0:raise ValueError("Invalid divider axis")
    ax,ay=ax/norm,ay/norm
    owned=[]
    try:
        footprints=[];sides=[]
        for blueprint,transform in sections:
            actor=world.try_spawn_actor(blueprint,transform)
            if actor is None:raise ValueError("Native barrier section spawn failed")
            owned.append(actor)
            vertices=actor.bounding_box.get_world_vertices(actor.get_transform())
            if len(vertices)<4:raise ValueError("Missing realized barrier vertices")
            footprint=MultiPoint([_xy(v) for v in vertices]).convex_hull
            if footprint.area<=0 or footprint.intersects(opening):
                raise ValueError("Barrier section overlaps or closes opening")
            footprints.append(footprint)
            relative=footprint.centroid
            sides.append((relative.x-opening.centroid.x)*ax+(relative.y-opening.centroid.y)*ay)
        if sides[0]*sides[1]>=0:raise ValueError("Barrier sections do not straddle opening")
        yield {"actors":owned,"opening_xy_m":list(opening.exterior.coords),
               "barrier_footprints_xy_m":[list(p.exterior.coords) for p in footprints],
               "section_axis_offsets_m":sides}
    finally:
        for actor in reversed(owned):actor.destroy()

"""Retain original Native vehicle bodies and four synchronized camera sources.

The caller supplies a reviewed site and an image writer for each camera. This
module does not infer public authority or physical success from a route plan.
"""

from contextlib import contextmanager
import json
import math
from queue import Empty, Queue

from shapely.geometry import MultiPoint, Polygon

CAMERAS = {'overview': (1920, 1080), 'approach': (1280, 720),
           'reference_corner': (1280, 720), 'driver_reference': (1280, 720)}


def _finite(value, label):
    if type(value) not in (float, int) or not math.isfinite(value):
        raise ValueError('Finite original Native ' + label + ' required')
    return float(value)


def _body(actor, label):
    vertices = actor.bounding_box.get_world_vertices(actor.get_transform())
    if len(vertices) < 4:
        raise ValueError('Complete original Native ' + label + ' body required')
    points = [[_finite(v.x, label + ' body x'), _finite(v.y, label + ' body y')]
              for v in vertices]
    if MultiPoint(points).convex_hull.area <= 0:
        raise ValueError('Degenerate original Native ' + label + ' body')
    return points


def _validate_context(context):
    keys = ('native_map_id', 'divided_highway_source', 'roadway_boundaries_source',
            'opening_geometry_source', 'barrier_actors_source', 'other_vehicle_source')
    if any(not context.get(key) for key in keys):
        raise ValueError('Reviewed divided-road source context required')
    for key in ('right_hand_roadway_xy_m', 'destination_roadway_xy_m',
                'dividing_space_xy_m', 'opening_xy_m'):
        shape = Polygon(context[key])
        if not shape.is_valid or shape.area <= 0:
            raise ValueError('Invalid reviewed ' + key)
    if not Polygon(context['dividing_space_xy_m']).covers(Polygon(context['opening_xy_m'])):
        raise ValueError('Opening outside reviewed divider')


@contextmanager
def original_cameras(world, ego, transforms, timeout_s=10):
    """Create four real RGB sensors and yield exact-tick image readers."""
    if set(transforms) != set(CAMERAS) or timeout_s <= 0:
        raise ValueError('Four camera poses and positive timeout required')
    queues = {name: Queue() for name in CAMERAS}
    sensors = []
    try:
        for name, (width, height) in CAMERAS.items():
            blueprint = world.get_blueprint_library().find('sensor.camera.rgb')
            if blueprint is None:
                raise ValueError('Native RGB camera blueprint missing')
            for key, value in (('image_size_x', width), ('image_size_y', height),
                               ('fov', 90), ('sensor_tick', 0.05)):
                blueprint.set_attribute(key, str(value))
            kwargs = {'attach_to': ego} if name == 'driver_reference' else {}
            sensor = world.spawn_actor(blueprint, transforms[name], **kwargs)
            if sensor is None:
                raise ValueError('Native camera spawn failed: ' + name)
            sensors.append(sensor)
            sensor.listen(lambda image, source=name: queues[source].put(image))

        def read(frame):
            images = {}
            for name in CAMERAS:
                for _ in range(8):
                    try:
                        image = queues[name].get(timeout=timeout_s)
                    except Empty as error:
                        raise ValueError('Missing original camera frame: ' + name) from error
                    if image.frame == frame:
                        if (image.width, image.height) != CAMERAS[name]:
                            raise ValueError('Original camera dimensions differ: ' + name)
                        images[name] = image
                        break
                    if image.frame > frame:
                        raise ValueError('Original camera skipped Native frame: ' + name)
                else:
                    raise ValueError('Original camera backlog exceeded: ' + name)
            return images

        yield read
    finally:
        for sensor in reversed(sensors):
            sensor.stop()
            sensor.destroy()


class OriginalTickRecorder:
    """Write frame-bound measurement sources after all four images are retained."""

    def __init__(self, context, movement_stream, frame_stream, camera_writers):
        _validate_context(context)
        if set(camera_writers) != set(CAMERAS):
            raise ValueError('All four original camera writers required')
        self.context = context
        self.movement_stream = movement_stream
        self.frame_stream = frame_stream
        self.camera_writers = camera_writers
        self.index = 0
        self.last_frame = -1
        self.last_time = -math.inf

    def record(self, snapshot, ego, other, images, road_id=None):
        frame = snapshot.frame
        time_s = _finite(snapshot.timestamp.elapsed_seconds, 'time')
        if type(frame) is not int or frame <= self.last_frame or time_s <= self.last_time:
            raise ValueError('Nonmonotone original Native tick')
        if ego.id == other.id:
            raise ValueError('Distinct original Native participants required')
        if set(images) != set(CAMERAS) or any(
                image.frame != frame or (image.width, image.height) != CAMERAS[name]
                for name, image in images.items()):
            raise ValueError('Four original camera frames must join Native tick')
        pose = ego.get_transform()
        yaw = math.radians(_finite(pose.rotation.yaw, 'ego yaw'))
        row = {'frame': frame, 'time_s': time_s,
               'ego_actor_id': ego.id, 'other_actor_id': other.id,
               'ego_body_vertices_xy_m': _body(ego, 'ego'),
               'other_body_vertices_xy_m': _body(other, 'other'),
               'ego_forward_xy': [math.cos(yaw), math.sin(yaw)],
               'heading_deg': math.degrees(yaw), 'road_id': road_id}
        for name, image in images.items():
            self.camera_writers[name](image)
        self.movement_stream.write(json.dumps(row, allow_nan=False) + '\n')
        if hasattr(self.frame_stream, 'append'):
            mapped = self.frame_stream.append(frame, time_s)
            if mapped['video_frame'] != self.index or mapped['carla_frame'] != frame:
                raise ValueError('Canonical original frame map differs')
        else:
            self.frame_stream.write(json.dumps({'video_frame': self.index,
                                                'carla_frame': frame,
                                                'native_frame': frame,
                                                'time_s': time_s}, allow_nan=False) + '\n')
        self.index += 1
        self.last_frame, self.last_time = frame, time_s
        return row

"""Lossless original Native RGB camera source writer for a fresh capture attempt."""

from pathlib import Path
import subprocess


class FFV1Writer:
    def __init__(self, path, width, height, fps=20):
        path = Path(path)
        if path.exists() or not path.parent.is_dir() or min(width, height, fps) <= 0:
            raise ValueError('Fresh camera path and positive source profile required')
        self.path, self.width, self.height, self.fps = path, width, height, fps
        self.frames = 0
        self.exit_code = None
        self.process = subprocess.Popen([
            'ffmpeg', '-hide_banner', '-loglevel', 'error', '-n',
            '-f', 'rawvideo', '-pixel_format', 'bgra',
            '-video_size', f'{width}x{height}', '-framerate', str(fps),
            '-i', 'pipe:0', '-an', '-c:v', 'ffv1', '-level', '3',
            '-pix_fmt', 'bgr0', str(path)], stdin=subprocess.PIPE,
            stderr=subprocess.PIPE)

    def write(self, image):
        if (image.width, image.height) != (self.width, self.height):
            raise ValueError('Original Native camera dimensions differ')
        bgra = bytes(image.raw_data)
        if len(bgra) != self.width * self.height * 4:
            raise ValueError('Incomplete original Native BGRA frame')
        if self.process.poll() is not None:
            raise ValueError('Original camera encoder exited before frame closure')
        self.process.stdin.write(bgra)
        self.frames += 1

    def close(self):
        if self.exit_code is not None:
            return self.exit_code
        if not self.process.stdin.closed:
            self.process.stdin.close()
        try:
            code = self.process.wait(timeout=120)
        except subprocess.TimeoutExpired:
            self.process.kill()
            self.process.wait()
            code = self.process.returncode
        error = self.process.stderr.read().decode(errors='replace')
        self.process.stderr.close()
        self.exit_code = code
        if code != 0 or not self.path.is_file():
            raise ValueError('Original FFV1 camera encoder failed: ' + error[-1000:])
        return code

    def __enter__(self):
        return self

    def __exit__(self, *_):
        self.close()

"""Original-frame complete-body route through a divided-highway opening."""

import hashlib
import json
import math
from pathlib import Path

from shapely.geometry import MultiPoint, Polygon


REQUIRED=("divider_context.json","movement_history.jsonl","video_frames.jsonl")


def _number(value,label):
    if isinstance(value,bool) or not isinstance(value,(int,float)) or not math.isfinite(value):
        raise ValueError("Missing finite "+label)
    return float(value)


def _polygon(values,label):
    if not isinstance(values,list) or len(values)<3:raise ValueError("Missing "+label)
    poly=Polygon([(_number(v[0],label+" x"),_number(v[1],label+" y")) for v in values])
    if not poly.is_valid or poly.area<=0:raise ValueError("Invalid "+label)
    return poly


def _body(values):
    if not isinstance(values,list) or len(values)<4:raise ValueError("Missing complete body")
    body=MultiPoint([(_number(v[0],"body x"),_number(v[1],"body y")) for v in values]).convex_hull
    if body.area<=0:raise ValueError("Degenerate body")
    return body


def _rows(path):
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def analyze(root:Path)->dict:
    root=Path(root);hashes={}
    for name in REQUIRED:
        path=root/name
        if not path.is_file():raise ValueError("Missing original source: "+name)
        hashes[name]=hashlib.sha256(path.read_bytes()).hexdigest()
    ctx=json.loads((root/"divider_context.json").read_text())
    for key in ("native_map_id","divided_highway_source","roadway_boundaries_source",
                "opening_geometry_source","barrier_actors_source","other_vehicle_source"):
        if not ctx.get(key):raise ValueError("Missing sourced divider context: "+key)
    right=_polygon(ctx.get("right_hand_roadway_xy_m"),"right-hand roadway")
    destination=_polygon(ctx.get("destination_roadway_xy_m"),"destination roadway")
    divider=_polygon(ctx.get("dividing_space_xy_m"),"dividing space")
    opening=_polygon(ctx.get("opening_xy_m"),"opening")
    if not divider.covers(opening):raise ValueError("Opening not within dividing space")
    blocked=divider.difference(opening)
    rows,frames=_rows(root/"movement_history.jsonl"),_rows(root/"video_frames.jsonl")
    if len(rows)<4 or len(rows)!=len(frames):raise ValueError("Incomplete movement history")
    previous=(-1,-math.inf);samples=[]
    for i,(row,frame) in enumerate(zip(rows,frames)):
        fid,time=row.get("frame"),_number(row.get("time_s"),"time")
        if type(fid) is not int or fid<=previous[0] or time<=previous[1]:
            raise ValueError("Nonmonotone original history")
        previous=fid,time
        if frame.get("video_frame")!=i or frame.get("carla_frame")!=fid or frame.get("time_s")!=time:
            raise ValueError("Original frame join failed")
        ego=_body(row.get("ego_body_vertices_xy_m"))
        other=_body(row.get("other_body_vertices_xy_m"))
        heading=row.get("ego_forward_xy")
        if not isinstance(heading,list) or len(heading)!=2:raise ValueError("Missing ego heading")
        hx,hy=(_number(v,"ego heading") for v in heading)
        norm=math.hypot(hx,hy)
        if norm==0:raise ValueError("Zero ego heading")
        samples.append({"frame":fid,"time_s":time,"ego_in_right_roadway":ego.intersects(right),
                        "ego_in_destination_roadway":ego.intersects(destination),
                        "ego_in_opening":ego.intersects(opening),
                        "ego_over_divider_outside_opening":ego.intersects(blocked),
                        "other_body_distance_m":ego.distance(other),
                        "ego_forward_xy":[hx/norm,hy/norm]})
    first,last=samples[0],samples[-1]
    before,after=first["ego_forward_xy"],last["ego_forward_xy"]
    turn=math.degrees(math.atan2(before[0]*after[1]-before[1]*after[0],
                                 before[0]*after[0]+before[1]*after[1]))
    return {"format":"worker-divided-road-opening-observations","sources":hashes,
            "starts_on_right_hand_roadway":first["ego_in_right_roadway"],
            "ends_on_destination_roadway":last["ego_in_destination_roadway"],
            "opening_traversed_observed":any(s["ego_in_opening"] for s in samples),
            "any_body_overlap_outside_opening":any(s["ego_over_divider_outside_opening"] for s in samples),
            "observed_turn_angle_degrees":turn,"samples":samples,
            "public_authority_establishment_judgment":"unresolved",
            "legal_conclusion":"unresolved"}
